                title: change < 0
                    ? `ההכנסות ירדו ${Math.round(-change * 100)}% בחודש האחרון`
                    : `ההכנסות עלו ${Math.round(change * 100)}% בחודש האחרון`,
                detail: change < 0
                    ? 'זו ירידה בקצב הכניסות לחשבון, לא בהכרח במכירות — סליקה נכנסת באיחור של כשבוע.'
                    : 'הקצב שנכנס לחשבון עלה. אם זה נמשך, הצפי שמרני מדי.',
                evidence: `${ils(inc30)} ב-30 יום מול ${ils(incBase)} בממוצע לפני כן`,
